    scores={}
    for cat, pats in CATS.items():
        s=0
        for pat,w in pats:
            s += len(pat.findall(t))*w
        scores[cat]=s
    best=max(scores.items(), key=lambda kv: kv[1])
    if best[1]==0:
        # per instructions: last folder as catch-all
        return 'music_history', scores
    # tie-breaker: deterministic by score then fixed priority
    tied=[c for c,v in scores.items() if v==best[1]]
    if len(tied)>1:
        priority=['LLM','trapped_ion_and_qc','black_hole','DNA','music_history']
        for p in priority:
            if p in tied:
                return p, scores
    return best[0], scores

files=sorted([f for f in os.listdir(SRC) if os.path.isfile(os.path.join(SRC,f))])
counts=Counter()
for f in files:
    txt=extract_text(os.path.join(SRC,f))
    cat,_=classify(txt)
    counts[cat]+=1
print('--- counts ---')
for k in ['LLM','trapped_ion_and_qc','black_hole','DNA','music_history']:
