import os, re
from collections import Counter, defaultdict
from pypdf import PdfReader
from docx import Document
from pptx import Presentation

SRC='/root/papers/all'

CATS=[
  ('LLM', [
      'large language model','language model','llm','transformer','gpt','bert','t5','attention','prompt','token','in-context','few-shot','chatgpt','instruction tuning'
  ]),
  ('trapped_ion_and_qc', [
      'trapped ion','ion trap','paul trap','rf trap','mølmer–sørensen','molmer','cirac–zoller','cirac','ytterbium','calcium ion','barium ion','qubit','quantum computing','quantum computer','quantum gate','entanglement','superconducting qubit','quantum error correction','surface code'
  ]),
  ('black_hole', [
      'black hole','event horizon','hawking','schwarzschild','kerr','singularity','bekenstein','accretion','ads/cft','btz','gravitational collapse','no-hair theorem'
  ]),
  ('DNA', [
      'dna','genome','genomic','gene','genes','nucleotide','double helix','crispr','sequencing','polymerase','chromosome','base pair'
  ]),
  # music_history is fallback
]

# simple normalization
word_re=re.compile(r"[a-z0-9]+(?:[-'][a-z0-9]+)?")

def norm(text:str)->str:
    if not text:
        return ''
    text=text.lower()
    text=text.replace('\u00ad','')
    return text

def extract_text(path:str, max_pages=3, max_chars=200000):
    ext=os.path.splitext(path)[1].lower()
    try:
        if ext=='.pdf':
            r=PdfReader(path)
            parts=[]
            for i,p in enumerate(r.pages[:max_pages]):
                t=p.extract_text() or ''
                parts.append(t)
            t='\n'.join(parts)
            return t[:max_chars]
        if ext=='.docx':
            d=Document(path)
            t='\n'.join(p.text for p in d.paragraphs)
            return t[:max_chars]
        if ext=='.pptx':
            pres=Presentation(path)
            parts=[]
            for s in pres.slides:
                for shape in s.shapes:
                    if hasattr(shape,'text'):
                        parts.append(shape.text)
            t='\n'.join(parts)
            return t[:max_chars]
    except Exception:
        return ''
    return ''

def score(text:str):
    t=norm(text)
    # count keyword occurrences (substring)
    scores={}
    for cat, kws in CATS:
        s=0
        for kw in kws:
            if len(kw)<=3:
                # short keywords: match word boundary
                s += len(re.findall(rf"\\b{re.escape(kw)}\\b", t))
            else:
                s += t.count(kw)
        scores[cat]=s
    best=max(scores.items(), key=lambda kv: kv[1])
    if best[1]==0:
        return 'music_history', scores
    return best[0], scores

files=sorted([f for f in os.listdir(SRC) if os.path.isfile(os.path.join(SRC,f))])
assignments={}
counts=Counter()
examples=defaultdict(list)

for f in files:
    fp=os.path.join(SRC,f)
    txt=extract_text(fp)
    cat, scores=score(txt)
    assignments[f]=cat
    counts[cat]+=1
    if len(examples[cat])<5:
        top=sorted(scores.items(), key=lambda kv: kv[1], reverse=True)[:3]
        examples[cat].append((f, top))

print('--- dry-run counts ---')
for k,v in counts.most_common():
    print(f'{k:20s} {v}')

print('\n--- sample classifications (up to 5 each) ---')
for cat in ['LLM','trapped_ion_and_qc','black_hole','DNA','music_history']:
    if cat not in counts: continue
    print(f'\n[{cat}]')
    for f, top in examples[cat]:
        print(' ', f, ' top_scores=', top)
